ta"}},{"@type":"City","name":"St. Cloud","containedInPlace":{"@type":"State","name":"Minnesota"}},{"@type":"City","name":"Mankato","containedInPlace":{"@type":"State","name":"Minnesota"}},{"@type":"City","name":"Moorhead","containedInPlace":{"@type":"State","name":"Minnesota"}}],"hasOfferCatalog":{"@type":"OfferCatalog","name":"Insurance appraisal services","itemListElement":[{"@type":"Offer","itemOffered":{"@type":"Service","name":"Appraisal Clause Representation","url":"https://minnesotainsuranceappraiser.com/appraisal-solutions/appraisal-clause-help/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Homeowner Claim Appraisal","url":"https://minnesotainsuranceappraiser.com/appraisal-solutions/home-insurance-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Commercial, Townhome & HOA Claims","url":"https://minnesotainsuranceappraiser.com/appraisal-solutions/commercial-hoa-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Roof & Hail Damage Appraisal","url":"https://minnesotainsuranceappraiser.com/appraisal-solutions/hail-roof-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Tornado, Derecho & Straight-Line Wind","url":"https://minnesotainsuranceappraiser.com/appraisal-solutions/tornado-derecho-wind-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Water & Burst-Pipe Claims","url":"https://minnesotainsuranceappraiser.com/appraisal-solutions/water-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fire & Smoke Damage Appraisal","url":"https://minnesotainsuranceappraiser.com/appraisal-solutions/fire-smoke-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Ice Dam, Snow Load & Frozen Pipe Claims","url":"https://minnesotainsuranceappraiser.com/appraisal-solutions/ice-dam-winter-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Insurance Estimate Review","url":"https://minnesotainsuranceappraiser.com/appraisal-solutions/claim-estimate-review/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Umpire & Neutral Services","url":"https://minnesotainsuranceappraiser.com/appraisal-solutions/appraisal-umpire/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Contents & Personal Property Appraisal","url":"https://minnesotainsuranceappraiser.com/appraisal-solutions/contents-personal-property-appraisal/"}}]},"knowsAbout":["Insurance appraisal","Appraisal clause","Hail damage","Ice dams","Derecho and tornado wind damage","Xactimate estimating"],"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://minnesotainsuranceappraiser.com/#website","url":"https://minnesotainsuranceappraiser.com/","name":"Minnesota Insurance Appraiser","publisher":{"@id":"https://minnesotainsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://minnesotainsuranceappraiser.com/insurance-terms/#webpage","url":"https://minnesotainsuranceappraiser.com/insurance-terms/","name":"Insurance Claim Glossary | Appraisal & Policy Terms","description":"Searchable glossary of 50 property insurance terms: actual cash value, appraisal award, ice dam, matching, O&P, umpire and more.","inLanguage":"en-US","isPartOf":{"@id":"https://minnesotainsuranceappraiser.com/#website"},"about":{"@id":"https://minnesotainsuranceappraiser.com/#business"},"publisher":{"@id":"https://minnesotainsuranceappraiser.com/#business"},"dateModified":"2026-11-13","primaryImageOfPage":{"@type":"ImageObject","@id":"https://minnesotainsuranceappraiser.com/insurance-terms/#primaryimage","url":"https://minnesotainsuranceappraiser.com/assets/img/photos/calculator-chart.webp","width":960,"height":640},"breadcrumb":{"@id":"https://minnesotainsuranceappraiser.com/insurance-terms/#breadcrumb"},"mainEntity":{"@id":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://minnesotainsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Insurance terms","item":"https://minnesotainsuranceappraiser.com/insurance-terms/"}],"@id":"https://minnesotainsuranceappraiser.com/insurance-terms/#breadcrumb"},{"@type":"DefinedTermSet","name":"Minnesota property insurance claim terms","hasDefinedTerm":[{"@type":"DefinedTerm","name":"Actual Cash Value (ACV)","description":"Replacement cost minus depreciation. Many policies pay this amount first, before repairs are finished.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Additional Living Expense (ALE)","description":"Coverage for the extra cost of living elsewhere while a home is unlivable after a covered loss; often called loss of use or Coverage D.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Amount of Loss","description":"The dollar value of a covered loss. It is the question an appraisal panel is set up to decide.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Appraisal","description":"A policy-based process in which two appraisers and, if needed, an umpire determine the amount of a covered loss when the insured and insurer disagree.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Appraisal Award","description":"The written decision, signed by any two of the three panel members, that sets the amount of loss.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Bad Faith","description":"A general term for unreasonable claim handling by an insurer. In Minnesota, claims of this kind are legal matters for an attorney, not for an appraisal panel.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Causation","description":"What caused the damage, such as hail versus age-related wear. Minnesota courts have allowed appraisers to address causation as part of the amount of loss.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Claim Supplement","description":"A request to add items or increase pricing on an existing estimate, usually supported by new photos, bids or code requirements.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Coverage A (Dwelling)","description":"The part of a homeowners policy that pays to repair or rebuild the house itself and attached structures.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Coverage B (Other Structures)","description":"Coverage for detached structures on the property, such as a garage, shed or fence.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Declarations Page","description":"The summary page of a policy listing the named insured, property address, coverage limits, deductibles and policy period.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Deductible","description":"The portion of a covered loss the policyholder pays before insurance pays. Some policies use a separate wind or hail deductible.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Department of Commerce","description":"The Minnesota Department of Commerce, the state agency that regulates insurers and licenses agents, adjusters and public adjusters.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Depreciation","description":"A reduction in value for age, wear and condition, subtracted from replacement cost to arrive at actual cash value.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Derecho","description":"A long-lived, widespread windstorm with straight-line winds, such as the one that crossed southern Minnesota on May 12, 2022.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Disinterested Appraiser","description":"An appraiser with no financial stake in the outcome of the claim beyond a reasonable fee for services.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Drip Edge","description":"Metal flashing installed along roof edges to direct water into the gutters and protect the fascia and deck edge.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Estimate Review","description":"An independent check of an insurer’s or contractor’s estimate for missing items, measurement errors and pricing problems.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"FAIR Plan","description":"The Minnesota FAIR Plan, which offers basic property insurance when coverage isn’t available in the voluntary market.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Fascia","description":"The vertical board along the roof edge where gutters attach; often damaged by hail, wind and ice.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Gutter Apron","description":"A flashing piece that tucks under shingles and laps into the gutter to keep water from running behind it.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Hail Bruise","description":"A soft spot in a shingle where hail has fractured the mat beneath the granules, even if no hole is visible.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Ice and Water Shield","description":"A self-adhering waterproof membrane installed at eaves, valleys and penetrations to resist leaks from ice dams and wind-driven rain.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Ice Dam","description":"A ridge of ice at the roof edge that traps meltwater, which can back up under shingles and leak into walls and ceilings.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Insured","description":"The person or entity covered under the policy. See also named insured.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Joint Inspection","description":"A site visit attended by both appraisers, and sometimes the umpire, to measure and document the damage together.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Line Item","description":"A single entry in an estimate, such as removal of one square of shingles, with quantity, unit price and total.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Loss of Use","description":"Coverage for added living expenses or lost rental income when property can’t be used after a covered loss.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Matching","description":"The question of whether undamaged materials must be replaced so repairs reasonably match in color, texture and appearance.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Mortgagee Clause","description":"Policy wording that protects the lender’s interest; it is why claim checks often name the mortgage company as a payee.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Named Insured","description":"The person or entity listed on the declarations page as the policyholder.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Ordinance or Law Coverage","description":"Coverage for added costs to bring repaired portions of a building up to current building codes.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Overhead and Profit (O&P)","description":"A general contractor’s charge for managing a project and running a business, often 10 percent each, when the job requires coordinating several trades.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Proof of Loss","description":"A sworn statement of the amount claimed, which some policies require within a set time after the insurer asks for it.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Public Adjuster","description":"A professional licensed by the Minnesota Department of Commerce to represent policyholders in preparing and negotiating a claim.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Quade v. Secura","description":"A 2012 Minnesota Supreme Court decision recognizing that appraisers may decide causation as part of the amount of loss, while coverage remains for courts.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Recoverable Depreciation","description":"Depreciation withheld from an initial payment that can be recovered once repairs are completed, if the policy provides replacement cost coverage.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Replacement Cost Value (RCV)","description":"The cost to repair or replace damaged property with materials of like kind and quality, without a deduction for depreciation.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Scope of Loss","description":"The list of damaged items and the repairs needed, before pricing is applied.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Sewer Backup Endorsement","description":"Optional coverage for damage caused by water backing up through drains or sewers; many base policies exclude it.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Square (Roofing)","description":"A roofing unit equal to 100 square feet of roof surface.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Steel Siding","description":"Painted steel lap siding common on older Minnesota homes; dents easily in hail and is often hard to match once discontinued.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Suit Limitation","description":"A policy condition limiting how long you have to sue the insurer, commonly two years after the loss in Minnesota forms; confirm with an attorney.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Supplemental Payment","description":"An additional payment the insurer issues after approving a supplement or after an appraisal award.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Tear-Off","description":"Removal of existing roofing layers down to the deck before new roofing is installed.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Umpire","description":"The neutral third member of an appraisal panel who decides items the two appraisers cannot agree on.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Underlayment","description":"The protective layer between the roof deck and shingles, such as felt or synthetic sheet.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Valley","description":"The internal angle where two roof slopes meet; a common point for ice and water leaks.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Wind Deductible","description":"A separate deductible for wind or hail losses, sometimes stated as a percentage of the dwelling limit.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Xactimate","description":"Estimating software widely used by insurers, adjusters and contractors to build line-item repair estimates with regional pricing.","inDefinedTermSet":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"}],"@id":"https://minnesotainsuranceappraiser.com/insurance-terms/#definedtermset"}]}</script>
</head>
